/// Which end of a `line` / `arrow` shape a drag grabbed (spec §4.2's
/// endpoint handles). Distinct from `TimelineEdge`, which is a *time* edge.
enum CanvasEndpoint: Equatable {
    case from
    case to
}

/// What is under the pointer on the canvas. Computed once per press by
/// `PreviewCanvasView.hit(at:)` and handed to the session that owns that kind
/// of drag, so "what did I grab" is decided in one function instead of being
/// re-derived by every mouse handler.
enum CanvasHit: Equatable {
    case handle(UInt32, CanvasHandle)
    case rotation(UInt32)
    case cropHandle(UInt32, CanvasHandle)
    case endpoint(UInt32, CanvasEndpoint)
    case body(UInt32)
    /// The void, or the canvas with nothing under the pointer.
    case empty
}

// MARK: - A layer's box on the canvas

    /// The rotation grip, `offset` canvas pixels beyond the top edge along
    /// the box's own "up".
    func rotationHandlePoint(offset: CGFloat) -> CGPoint {
        let up = canvasRotate(CGVector(dx: 0, dy: -1), degrees: rotation)
        let top = handlePoint(.top)
        return CGPoint(x: top.x + up.dx * offset, y: top.y + up.dy * offset)
    }

    /// A line/arrow endpoint in canvas space. Endpoints are UNIT coordinates
    /// in the uncropped box (`ShapeProps.from` / `.to`).
    func endpointPoint(_ endpoint: CanvasEndpoint) -> CGPoint? {
        guard let shape = clip.shape, shape.kind.isLinear else { return nil }
        let unit = endpoint == .from ? shape.fromPoint : shape.toPoint
        let box = uncroppedRect
        return rotated(
            CGPoint(x: box.minX + unit.x * box.width, y: box.minY + unit.y * box.height))
    }

    /// The inverse: a canvas point as unit coordinates in the uncropped box,
    /// clamped to it.
    func endpointUnit(_ point: CGPoint) -> CGPoint {
        let box = uncroppedRect
        guard box.width > 0, box.height > 0 else { return .zero }
        let local = unrotated(point)
        return CGPoint(
            x: min(max((local.x - box.minX) / box.width, 0), 1),
            y: min(max((local.y - box.minY) / box.height, 0), 1))
    }

    // MARK: The region frame

    /// A canvas point as SOURCE pixels measured from the centre of the
    /// layer's CROPPED rect — the frame `video.spotlight`, `video.obscure`
    /// and `add_zoom_action`'s region all speak (`model_regions.rs`'s
    /// `Spotlight`, and `Compositor.metal`'s
    /// `centre = cropped * 0.5 + float2(spotX, spotY)`). Spec §5.3 calls it Q.
        }
        crop = CropInsets(
            l: canvasRound(l), t: canvasRound(t), r: canvasRound(r), b: canvasRound(b))
        didMove = true
    }
}

// MARK: - Shape endpoints

/// Dragging a `line` or `arrow` end (spec §4.2). The model stores them as
/// unit coordinates in the shape's box, so the box itself never changes.
struct CanvasEndpointSession {
    let clip: UInt32
    let endpoint: CanvasEndpoint
    var unit: CGPoint
    var didMove = false

    var op: ReelOp {
        let values = [canvasRound(unit.x), canvasRound(unit.y)]
        switch endpoint {
        case .from: return .setShape(clips: [clip], patch: ShapePatch(from: values))
        case .to: return .setShape(clips: [clip], patch: ShapePatch(to: values))
        }
    }

    /// `unit` comes from `CanvasLayerBox.endpointUnit`, which owns the
    /// rotation and the box maths.
    mutating func update(unit: CGPoint) {
        self.unit = unit
        didMove = true
    }
}

// MARK: - Chroma-key eyedropper

/// Picking the chroma key colour off the canvas (spec §4.3's "key color with
/// a canvas eyedropper"). One click, not a drag — and a session all the same,
/// because the sample cannot be taken while that click is being handled.
///
/// The preview's pixels belong to the Metal compositor, not to any view, so
/// the honest way to read one is to compose the frame again offline
/// (`Exporter.renderFrame` — the same `AVComposition` the export writes from,
/// so the pixel picked is the pixel the file would hold). That render opens
/// asset tracks and decodes, which has to happen off the main thread, and by
/// the time it lands the selection may have moved. Everything the click meant
/// is therefore captured here first: `EditorViewController+Eyedropper.swift`
/// runs it and compares this against the selection before it commits.
struct CanvasEyedropperSession {
    /// The clips the pick will key — the Video pane's video clips, in the
    /// order it offers them.
    let clips: [UInt32]
    /// The chroma those clips already carry, so a re-pick replaces the colour
    /// and keeps the tolerances the user dialled in.
    let base: ChromaProps?

    /// The op that makes the frame this samples FROM. Applied to a COPY of
    /// the project — pure, never published, never on the undo stack, the way
    /// `EditorViewController+Inspector`'s probe is (§5.5).
    ///
    /// It removes the three things standing between the pixel on screen and
    /// the number `Compositor.metal` actually compares against the key:
    ///
    ///  - the clip's own chroma, because a keyed pixel is a HOLE — the most
    ///    natural pick of all, "the green I can still see", would otherwise
    ///    sample whatever shows through it;
    ///  - its colour adjustment, tone, wheels, curves and look (GR-2, GR-11, GR-12, GR-7), as
    ///    the shader keys BEFORE them (§7.5's order of operations), so the adjusted pixel
    ///    is not the one being compared;
    ///  - its opacity, because a faded layer's pixel on screen is already
    ///    mixed with whatever lies behind it.
    ///
    /// What is left is a layer drawn exactly as the key sees it. A layer
    /// COVERED by another one is still covered — the pick is what is visible
    /// at that point, which is what a user aiming at it means.
    var suppression: ReelOp {
        .setVideo(clips: clips, patch: VideoPatch(
            built = CanvasLayerBox.boxes(snapshot: snapshot, at: playhead)
        }
        cachedBoxes = built
        return built
    }

    func box(for id: UInt32) -> CanvasLayerBox? { boxes.last { $0.id == id } }

    /// The selected layer the handles hang off: the front-most selected one,
    /// which is the one a click would have picked.
    var primaryBox: CanvasLayerBox? { boxes.last { selection.contains($0.id) } }

    // MARK: - Hit testing

    /// What is under `point` (view space). Handles win over bodies, and the
    /// primary selection's handles win over everything, so a handle sitting on
    /// top of another clip still grabs.
    func hit(at point: CGPoint) -> CanvasHit {
        if let box = primaryBox, !box.locked {
            let grab = Self.handleGrab
            if cropMode {
                for handle in CanvasHandle.allCases
                where near(canvasToView(box.cropHandlePoint(handle)), point, grab) {
                    return .cropHandle(box.id, handle)
                }
            } else {
                let offset = canvasDistance(Self.rotationOffset)
                if near(canvasToView(box.rotationHandlePoint(offset: offset)), point, grab) {
                    return .rotation(box.id)
                }
                for endpoint in [CanvasEndpoint.from, .to] {
                    guard let at = box.endpointPoint(endpoint) else { continue }
                    if near(canvasToView(at), point, grab) { return .endpoint(box.id, endpoint) }
                }
                for handle in CanvasHandle.allCases
                where near(canvasToView(box.handlePoint(handle)), point, grab) {
                    return .handle(box.id, handle)
                }
            }
        }
        let canvasPoint = viewToCanvas(point)
        // Front to back: the topmost VISIBLE clip wins. Locked tracks are not
        // hit (spec §4.2); hidden ones never reach the recipe at all.
        if let box = boxes.reversed().first(where: { !$0.locked && $0.contains(canvasPoint) }) {
            return .body(box.id)
        }
        return .empty
    }

    private func near(_ a: CGPoint, _ b: CGPoint, _ radius: CGFloat) -> Bool {
        abs(a.x - b.x) <= radius && abs(a.y - b.y) <= radius
    }

    // MARK: - Selection

    private func selectClip(_ id: UInt32, flags: NSEvent.ModifierFlags) {
        var next = selection
        if flags.contains(.shift) {
            if next.contains(id) { next.remove(id) } else { next.insert(id) }
        } else if !next.contains(id) {
            next = [id]
        }
        if next != selection {
            selection = next
            overlay.needsDisplay = true
        }
        onSelectionChanged?(next)
    }

    private func clearSelection() {
        guard !selection.isEmpty else { return }
        selection = []
        onSelectionChanged?([])
        overlay.needsDisplay = true
    }

    // MARK: - Crop mode

    /// C, or a double-click on a clip with pixels (spec §4.2). Refuses with
    /// no selection rather than entering a mode with no box in it.
    @discardableResult
            beginMove(anchor: id, at: point, flags: flags)

        case .handle(let id, let handle):
            beginScale(id, handle: handle)

        case .rotation(let id):
            beginRotate(id, at: point)

        case .cropHandle(let id, let handle):
            beginCrop(id, handle: handle)

        case .endpoint(let id, let endpoint):
            beginEndpoint(id, endpoint: endpoint)
        }
        overlay.needsDisplay = true
    }

    /// Mouse-dragged. Exactly one session is live; each turns the pointer into
    /// its own ops and pushes them as a live edit, so the box on screen is the
    /// core's own answer and a refused tick simply leaves the last good frame.
    func continueGesture(at point: CGPoint, flags: NSEvent.ModifierFlags) {
        if var session = panning {
            session.update(point: point)
            panning = session
            panOffset = session.offset
            layoutCanvas()
            overlay.needsDisplay = true
            return
        }
        // ⌘ suppresses snapping while the drag is in flight, not only at the
        // press; the candidate list the gesture fetched is kept.
        snapper = CanvasSnapper(
            xs: snapper.xs, ys: snapper.ys,
            threshold: CanvasSnapper.tick(canvasDistance(CanvasSnapper.threshold)),
            enabled: snappingEnabled && !flags.contains(.command))
        let canvasPoint = viewToCanvas(point)
        if var session = moving {
            session.update(point: canvasPoint, snapper: snapper)
            moving = session
            onLiveUpdate?(session.ops(to: gestureTarget))
        } else if var session = scaling {
            session.update(
                point: canvasPoint, aspectFree: flags.contains(.shift),
                aboutCentre: flags.contains(.option))
            scaling = session
            onLiveUpdate?(session.ops(to: gestureTarget))
        } else if var session = rotating {
            session.update(point: canvasPoint, snapping: flags.contains(.shift))
            rotating = session
            onLiveUpdate?([session.op(to: gestureTarget)])
        } else if var session = cropping {
            session.update(point: canvasPoint)
            cropping = session
            onLiveUpdate?([session.op(to: gestureTarget)])
        } else if var session = endpointDrag {
            guard let box = box(for: session.clip) else { return }
            session.update(unit: box.endpointUnit(canvasPoint))
            endpointDrag = session
            onLiveUpdate?([session.op])
        } else if obscureDrag != nil {
            continueObscureDrag(at: canvasPoint, flags: flags)
        }
        overlay.needsDisplay = true
    }

    /// Mouse-up. Closes the live edit as ONE undo step (§7.6); a gesture that
    /// changed nothing registers none, because `endLiveEdit` compares handles.
    func endGesture(at point: CGPoint, flags: NSEvent.ModifierFlags) {
        if panning != nil {
            panning = nil
        } else if moving != nil {
            moving = nil
            onLiveEnd?("Move")
        } else if scaling != nil {
            scaling = nil
            onLiveEnd?("Scale")
        } else if rotating != nil {
            rotating = nil
            onLiveEnd?("Rotate")
        } else if cropping != nil {
            cropping = nil
            onLiveEnd?("Crop")
        } else if endpointDrag != nil {
            endpointDrag = nil
            onLiveEnd?("Move Endpoint")
        } else if let session = obscureDrag {
            obscureDrag = nil
            onLiveEnd?(session.undoName)
        }
        overlay.needsDisplay = true
        window?.invalidateCursorRects(for: overlay)
    }

    /// Double-click: a text clip opens its inline editor, anything with pixels
    /// enters crop mode (spec §4.2).
    private func doubleClicked(_ id: UInt32) {
        guard let clip = snapshot.clip(id) else { return }
        if clip.text != nil, case .text = clip.source {
            beginTextEditing(id)
            return
        }
        if setCropMode(true) { return }
        NSSound.beep()
    }

    private func beginMove(anchor: UInt32, at point: CGPoint, flags: NSEvent.ModifierFlags) {
        let ids = selection.contains(anchor) ? selection : [anchor]
        var bases: [UInt32: CGPoint] = [:]
        gestureTarget = editTarget
        for id in ids {
            guard let clip = snapshot.clip(id),
                  snapshot.track(clip.track)?.locked != true
            else { continue }
            let props = gestureTarget.start(of: clip, in: project).video
            bases[id] = CGPoint(x: props.x, y: props.y)
        }
        guard !bases.isEmpty, let box = box(for: anchor) else { return }
        snapper = makeSnapper(excluding: Set(bases.keys), suppressed: flags.contains(.command))
        moving = CanvasMoveSession(
            bases: bases, anchor: anchor, anchorBounds: box.bounds, grab: viewToCanvas(point))
        onLiveBegin?()
    }

    private func beginScale(_ id: UInt32, handle: CanvasHandle) {
        guard let box = box(for: id), let clip = snapshot.clip(id) else { return }
        let route = editTarget.forScale(of: clip)
        gestureTarget = route
        let start = route.start(of: clip, in: project)
        let base = start.video
        let rect = startRect(of: box, base: base)
        let target: CanvasScaleTarget
    private func beginCrop(_ id: UInt32, handle: CanvasHandle) {
        guard let box = box(for: id), let clip = snapshot.clip(id) else { return }
        gestureTarget = editTarget
        let base = gestureTarget.start(of: clip, in: project).video
        cropping = CanvasCropSession(
            clip: id, handle: handle, base: base, sourceSize: box.sourceSize,
            startRect: startRect(of: box, base: base), rotation: base.rotation, crop: base.crop)
        onLiveBegin?()
    }

    private func beginEndpoint(_ id: UInt32, endpoint: CanvasEndpoint) {
        guard let clip = snapshot.clip(id), let shape = clip.shape else { return }
        endpointDrag = CanvasEndpointSession(
            clip: id, endpoint: endpoint,
            unit: endpoint == .from ? shape.fromPoint : shape.toPoint)
        onLiveBegin?()
    }

    /// The uncropped rectangle a session starts from, computed from the
    /// target's props (what the op merges into, CI-13) rather than the
    /// recipe's evaluated ones — the two differ only once a clip has actions.
    private func startRect(of box: CanvasLayerBox, base: VideoProps) -> CGRect {
        canvasRect(
            of: box.clip, in: snapshot.canvas, sourceSize: box.sourceSize, video: base.uncropped)
    }

    // MARK: - Keyboard

    /// The keys the canvas owns while it holds first responder. Everything
    /// else returns false and walks the responder chain to
    /// `EditorViewController.keyDown` (the bare-key transport map).
    func handleKey(_ event: NSEvent) -> Bool {
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        guard flags.subtracting(.shift).isEmpty else { return false }
        switch event.keyCode {
        case 53:  // Esc
            if cancelGesture() { return true }
            guard cropMode else { return false }
            setCropMode(false)
            return true
        case 36, 76:  // Return, keypad Enter
    /// which owns nothing but the event forwarding.
    func drawOverlay(in dirtyRect: CGRect) {
        guard canvasFrame.width > 2, canvasScale > 0 else { return }
        if cropMode, let box = primaryBox { drawCropGhost(box) }
        for box in boxes where selection.contains(box.id) {
            strokeBox(box, emphasised: box.id == primaryBox?.id)
