                    CanvasHandle.allCases.map { box.cropHandlePoint($0) }, fill: DS.snapGuide)
            } else {
                drawRotationGrip(box)
                drawHandles(CanvasHandle.allCases.map { box.handlePoint($0) }, fill: .white)
                drawEndpoints(box)
            }
        }
        drawSnapGuides()
